INSERT INTO skillforge_seed VALUES
  ('Isolate the variable in a nested expression 1', 'Solve 3(x − 5) + 2 = -1.', '5', '6', '4', '3', 'C', 'Expand to 3x − 15 + 2 = -1; add 15 and subtract 2, then divide by 3 to obtain x = 4.', 'Mathematics', 'easy'),
  ('Find the effective price after two reductions 2', 'A tool kit is marked at ₹180. A member discount of 10% is followed by a further 5% reduction on the discounted price. What percentage of the marked price is paid?', '85', '92.5', '85.5', '99.85', 'C', 'The reductions apply successively: (1 − 10/100)(1 − 5/100) = 0.8550. The final price is 85.5% of the marked price.', 'Mathematics', 'easy'),
  ('Calculate a without-replacement draw probability 3', 'A pouch has 5 red and 6 blue counters. Two counters are drawn without replacement. What is the probability both are red?', '5/11', '25/121', '20/110', '20/121', 'C', 'The first red probability is 5/11; after a red is removed, it is 4/10. Multiply to get 20/110.', 'Mathematics', 'easy'),
  ('Use a scale factor to recover a triangle area 4', 'A triangular panel has base 8 cm and height 5 cm. A scale drawing enlarges each length by a factor of 7. What is the area of the enlarged triangle in cm²?', '1960', '490', '980', '140', 'C', 'Area scales with the square of the length factor. The original area is 40/2; multiply by 7² to get 980 cm².', 'Mathematics', 'easy'),
