-- SkillForge 2.0 question bank. Safe to rerun; existing submissions and question IDs are preserved.
BEGIN;
SELECT pg_advisory_xact_lock(204857302);

-- Canonicalize legacy category labels without deleting or replacing question rows.
UPDATE questions SET category = 'Mathematics' WHERE LOWER(category) = 'maths';
UPDATE questions SET category = 'IQ' WHERE LOWER(category) IN ('iq & logic', 'iq and logic');
UPDATE questions SET category = 'Mental Ability' WHERE LOWER(category) = 'mental maths';

CREATE TEMP TABLE skillforge_seed (title text, description text, option_a text, option_b text, option_c text, option_d text, correct_option text, explanation text, category text, difficulty text) ON COMMIT DROP;
;
UPDATE questions q SET description=s.description, option_a=s.option_a, option_b=s.option_b, option_c=s.option_c, option_d=s.option_d, correct_option=s.correct_option, explanation=s.explanation, difficulty=s.difficulty FROM skillforge_seed s WHERE LOWER(q.category)=LOWER(s.category) AND LOWER(q.title)=LOWER(s.title);

DO $$ DECLARE bad_count integer; BEGIN
  IF EXISTS (SELECT 1 FROM questions WHERE category IN ('Mathematics','EQ','IQ','Aptitude','Mental Ability','Puzzles') AND (correct_option NOT IN ('A','B','C','D') OR btrim(option_a)='' OR btrim(option_b)='' OR btrim(option_c)='' OR btrim(option_d)='' OR explanation IS NULL OR btrim(explanation)='')) THEN
    RAISE EXCEPTION 'SkillForge 2.0 seed verification failed: incomplete question content';
  END IF;
  IF EXISTS (SELECT 1 FROM (VALUES ('Mathematics','easy',30),('Mathematics','medium',40),('Mathematics','hard',30),('EQ','easy',30),('EQ','medium',40),('EQ','hard',30),('IQ','easy',30),('IQ','medium',40),('IQ','hard',30),('Aptitude','easy',30),('Aptitude','medium',40),('Aptitude','hard',30),('Mental Ability','easy',30),('Mental Ability','medium',40),('Mental Ability','hard',30),('Puzzles','easy',30),('Puzzles','medium',40),('Puzzles','hard',30)) expected(category,difficulty,total) LEFT JOIN questions q ON q.category=expected.category AND q.difficulty=expected.difficulty GROUP BY expected.category,expected.difficulty,expected.total HAVING COUNT(q.id)<>expected.total) THEN
    RAISE EXCEPTION 'SkillForge 2.0 seed verification failed: difficulty distribution does not match 30/40/30';
  END IF;
  IF EXISTS (SELECT 1 FROM (VALUES ('Mathematics'),('EQ'),('IQ'),('Aptitude'),('Mental Ability'),('Puzzles')) expected(category) WHERE (SELECT COUNT(*) FROM questions q WHERE q.category=expected.category) < 100) THEN
    RAISE EXCEPTION 'SkillForge 2.0 seed verification failed: one or more categories has fewer than 100 questions';
  END IF;
  IF EXISTS (SELECT 1 FROM questions WHERE category IN ('Mathematics','EQ','IQ','Aptitude','Mental Ability','Puzzles') GROUP BY category,LOWER(title) HAVING COUNT(*)>1) THEN
    RAISE EXCEPTION 'SkillForge 2.0 seed verification failed: duplicate category/title found';
  END IF;
END $$;

COMMIT;

-- Verify totals and difficulty distribution after applying the seed:
-- SELECT category, difficulty, COUNT(*) FROM questions WHERE category IN ('Mathematics','EQ','IQ','Aptitude','Mental Ability','Puzzles') GROUP BY category,difficulty ORDER BY category,difficulty;
